const memoLru = (fn, max = 256) => {
  const cache = new Map();
  return (key) => {
    if (cache.has(key)) {
      const v = cache.get(key); cache.delete(key); cache.set(key, v);   // refresh recency
      return v;
    }
    const v = fn(key);
    cache.set(key, v);
    if (cache.size > max) cache.delete(cache.keys().next().value);      // evict oldest
    return v;
  };
};
